)
insert into public.layout_rooms(layout_type_id,room_number,room_type,name_ru,name_tg,area,position_x_percent,position_y_percent,description_ru,description_tg,sort_order,is_active,created_at,updated_at)
select l.id,p.room_number,p.room_type,p.name_ru,p.name_tg,p.area,p.position_x_percent,p.position_y_percent,p.description_ru,p.description_tg,p.sort_order,p.is_active,now()::text,now()::text
from payload p join public.layout_types l on l.code=p.code and l.project_id=3
where not exists(select 1 from public.layout_rooms r where r.layout_type_id=l.id);
update public.layout_types set description_ru=coalesce(description_ru,description,'') || E'\n\nПримечание к техническому чертежу: сумма подписанных площадей помещений составляет 78,90 м², а общая площадь в каталоге — 78,55 м². Расхождение 0,35 м² требует уточнения по утверждённому проекту.',
 description_tg=coalesce(description_tg,'') || E'\n\nЭзоҳ ба нақшаи техникӣ: ҷамъи масоҳатҳои навишташудаи ҳуҷраҳо 78,90 м² аст, вале масоҳати умумӣ дар феҳрист 78,55 м² мебошад. Фарқи 0,35 м² бояд аз рӯйи лоиҳаи тасдиқшуда дақиқ карда шавад.',updated_at=now()::text
where project_id=3 and code='CEILING315-10-A-6' and coalesce(description_ru,'') not like '%78,90%';
commit;
